scripts.姚公子对话.txt:
// 与姚公子的同伴对话

	If ($Event == 307) @Event307;
	Return;
	
@Event307:
	Say("独孤剑：如果你以后再敢鱼肉百姓，我可饶不了你！", 5);
	Say("姚公子：不敢，不敢，我再也不敢啦……", 71);
	Return;

scripts.张琳心对话.txt:
// 与张琳心的同伴对话

	If ($Event == 300) @Event300;
	If ($Event == 301) @Event301;
	If ($Event == 307) @Event307;
	If ($Event == 360) @Event360;
	
	Return;
	
@Event300:
	Say("张琳心：咱们四处问问，看看有什么李三的消息。", 21);
	Return;

@Event301:
	Say("张琳心：怎样才能救李三呢？", 21);
	Return;
			
@Event307:
	Say("张琳心：我们快去大牢救李三吧。", 21);
	Return;	
	
@Event360:
	Say("张琳心：我们快去找那个华山派弟子吧。", 21);
	Say("独孤剑：他下山的时候说去妓院，此刻可能还在那里。", 1);
	Return;

scripts.客栈掌柜对话.txt:
// 与客栈掌柜的对话
	
	CheckYear($Value);  
	If ($Value == 0) @NotYuanDan;	
	If ($Value == 1) @YuanDan;	
	
@NotYuanDan:
	
	If ($Event == 304) @zhang;
	If ($Event == 305) @zhang;
	
	Say("客栈老板：客官要住店吗？十两银子一晚上，家属不另外收钱，小店够意思吧？", 85);
	Say("独孤剑：不好意思，我不住店。", 2);
	Say("客栈老板：不住店就别在我这里晃悠！", 85):
	Return;
	
@zhang:
	Say("客栈老板：我们客栈不让醉酒者投宿，你还是到别处去吧！", 85);
	Return;	
	
	
@YuanDan:	

	If ($Event == 304) @zhangYD;
	If ($Event == 305) @zhangYD;
	
	Say("客栈老板：新年好！客官要住店吗？十两银子一晚上，家属不另外收钱，小店够意思吧？", 85);
	Say("独孤剑：不好意思，我不住店。", 2);
	Say("客栈老板：不住店就别在我这里晃悠！", 85):
	Return;
	
@zhangYD:
	Say("客栈老板：我们客栈不让醉酒者投宿，你还是到别处去吧！", 85);
	Return;

scripts.房客方远对话.txt:
// 房客方远对话

	Say("房客方远：岳飞、韩世忠等元帅率八十万宋兵在朱仙镇附近抵抗金兵，金兵对大小道路防范甚严，我只好绕道长安，成都，恩施，衡阳去临安了。");
	Return;

scripts.客栈店小二对话.txt:
// 与客栈掌柜的对话
	
	CheckYear($Value);  
	If ($Value == 0) @NotYuanDan;	
